/**
 * Pagination interface designed to be extended for list interfaces.
 *
 * @interface Pagination
 * @property {number} limit Number of items to return. When omitted the service returns up to 20. A limit
 *  above 100 returns at most 100 items; a limit below 1 is rejected.
 * @property {string} nextToken A token generated by a previous call. Omit for the first page.
 */
export interface Pagination {
  limit?: number
  nextToken?: string
}
